#!/usr/bin/env node
// Inlines src/look/glsl/*.glsl into src/look/glsl/chunks.ts so they ship through tsc unchanged.
import fs from "node:fs";
import path from "node:path";
const dir = path.resolve("src/look/glsl");
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".glsl")).sort();
const body = files.map((f) => `export const ${path.basename(f, ".glsl")}Glsl = ${JSON.stringify(fs.readFileSync(path.join(dir, f), "utf8"))};`).join("\n");
const out = `// GENERATED by tools/build-glsl.mjs from src/look/glsl/*.glsl — edit the .glsl files.\n${body}\n` +
  `export const allGlsl = [${files.map((f) => `${path.basename(f, ".glsl")}Glsl`).join(", ")}].join("\\n");\n`;
const target = path.join(dir, "chunks.ts");
if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== out) fs.writeFileSync(target, out);
